import seed from './project-data.json' with { type: 'json' };
export interface Surface { id: string; slug: string; label: string; components: readonly string[] }
export const project = Object.freeze({ ...seed, pages: Object.freeze(seed.pages.map(page => Object.freeze({ ...page, components: Object.freeze([...page.components]) }))) });
/** One host-free navigation model for every selected runtime. Business behavior is not inferred. */
export function createSession() {
  const pages: readonly Surface[] = project.pages;
  if (!pages.length) throw new Error('PROJECT_EMPTY');
  let current = pages[0]!;
  return {
    pages,
    get current(): Surface { return current; },
    select(id: string): Surface {
      const next = pages.find(page => page.id === id || page.slug === id);
      if (!next) throw new Error('PROJECT_SURFACE_UNKNOWN');
      current = next; return current;
    },
    reset(): Surface { current = pages[0]!; return current; },
  };
}

