import assert from 'node:assert/strict';
import { test } from 'node:test';
import { createSession, project } from '../src/core/project.ts';
test('each surface is reachable by stable ID and slug; failed selection preserves state', () => {
  const session = createSession();
  for (const page of project.pages) {
    assert.equal(session.select(page.id).id, page.id);
    assert.equal(session.select(page.slug).id, page.id);
    assert.throws(() => session.select('missing-surface'), /PROJECT_SURFACE_UNKNOWN/);
    assert.equal(session.current.id, page.id);
  }
  assert.equal(session.reset().id, project.pages[0].id);
});
test('independent runtime sessions do not leak in-memory selection', () => {
  const first = createSession(), second = createSession();
  first.select(project.pages.at(-1).id);
  assert.equal(second.current.id, project.pages[0].id);
});
test('runtime seed is immutable and reset returns the entry surface', () => {
  const session = createSession(); session.select(session.pages.at(-1).id);
  assert.equal(session.reset().id, session.pages[0].id);
  assert.throws(() => { project.pages[0].label = 'Changed'; }, TypeError);
  assert.throws(() => { project.pages.push(project.pages[0]); }, TypeError);
});

