import { bindTheme, type ObserveOwner } from './theme.ts';
import { createSession, project } from '../core/project.ts';
export function mount(host: HTMLElement, observeOwner?: ObserveOwner): () => void {
  const session = createSession(), doc = host.ownerDocument;
  const root = doc.createElement('section'); root.className = `${project.id} ps--${project.id} project-root`;
  root.dataset.pluginUi = project.id;
  const nav = doc.createElement('nav'); nav.setAttribute('aria-label', 'Project pages');
  const main = doc.createElement('main'), heading = doc.createElement('h1'), note = doc.createElement('p');
  const components = doc.createElement('ul');
  note.textContent = 'Prototype scaffold. Implement and test the agreed behavior; no business action is completed here.';
  main.append(heading, note, components); root.append(nav, main); host.append(root);
  let closeTheme: () => void;
  try { closeTheme = bindTheme(root, observeOwner); } catch (error) { root.remove(); throw error; }
  const buttons: HTMLButtonElement[] = [];
  function render(): void {
    heading.textContent = session.current.label;
    components.replaceChildren(...session.current.components.map(label => {
      const item = doc.createElement('li'); item.textContent = label + ' — component placeholder'; return item;
    }));
    for (const button of buttons) button.setAttribute('aria-current', button.dataset.page === session.current.id ? 'page' : 'false');
  }
  for (const page of session.pages) {
    const button = doc.createElement('button'); button.type = 'button'; button.textContent = page.label; button.dataset.page = page.id;
    button.addEventListener('click', () => { session.select(page.id); render(); }); nav.append(button); buttons.push(button);
  }
  render();
  return () => { try { closeTheme(); } finally { root.remove(); } };
}

