import { createApp } from 'vue';
import ui from '@nuxt/ui/vue-plugin';
import App from './App.vue';
import { project } from '../core/project.ts';
export function mount(host: HTMLElement, observeOwner?: ObserveOwner): () => void {
  const root = host.ownerDocument.createElement('section');
  root.className = `${project.id} ps--${project.id} project-root`; root.dataset.pluginUi = project.id; host.append(root);
  let closeTheme: () => void;
  try { closeTheme = bindTheme(root, observeOwner); } catch (error) { root.remove(); throw error; }
  const app = createApp(App);
  try { app.use(ui); app.mount(root); } catch (error) {
    try { app.unmount(); } catch { console.error('PROJECT_MOUNT_CLEANUP_FAILED'); }
    closeTheme(); root.remove(); throw error;
  }
  let disposed = false;
  return () => { if (disposed) return; disposed = true; try { app.unmount(); } finally { try { closeTheme(); } finally { root.remove(); } } };
}

