import { bindTheme, type ObserveOwner } from './theme.ts';
import { DOCUMENT } from '@angular/common';
import { createComponent, provideZonelessChangeDetection } from '@angular/core';
import { createApplication } from '@angular/platform-browser';
import { ProjectComponent } from './project.component.ts';
import { project } from '../core/project.ts';
export async function mount(host: HTMLElement, observeOwner?: ObserveOwner): Promise<() => void> {
  const app = await createApplication({ providers: [provideZonelessChangeDetection(), { provide: DOCUMENT, useValue: host.ownerDocument }] });
  const root = host.ownerDocument.createElement('section');
  root.className = `${project.id} ps--${project.id} project-root`; root.dataset.pluginUi = project.id; host.append(root);
  let closeTheme: () => void;
  try { closeTheme = bindTheme(root, observeOwner); } catch (error) { app.destroy(); root.remove(); throw error; }
  try {
    const component = createComponent(ProjectComponent, { hostElement: root, environmentInjector: app.injector });
    app.attachView(component.hostView); component.changeDetectorRef.detectChanges();
    let disposed = false;
    return () => {
      if (disposed) return; disposed = true;
      try { app.detachView(component.hostView); } finally {
        try { component.destroy(); } finally { try { app.destroy(); } finally { try { closeTheme(); } finally { root.remove(); } } }
      }
    };
  } catch (error) {
    try { app.destroy(); } catch { console.error('PROJECT_MOUNT_CLEANUP_FAILED'); }
    closeTheme(); root.remove(); throw error;
  }
}

