import { ItemView, Notice, Plugin, type WorkspaceLeaf } from 'obsidian';
import { project } from '../../core/project.ts';
import { mount } from '../../presentation/mount.ts';
import '../../styles/app.css';
const viewType = `${project.id}-workspace`;
class ProjectView extends ItemView {
  private generation = 0;
  private cleanup?: () => void;
  private readonly closed: (view: ProjectView) => void;
  constructor(leaf: WorkspaceLeaf, closed: (view: ProjectView) => void) { super(leaf); this.closed = closed; }
  getViewType(): string { return viewType; }
  getDisplayText(): string { return project.name; }
  async onOpen(): Promise<void> {
    this.dispose(); const generation = this.generation;
    try {
      const cleanup = await mount(this.contentEl, refresh => {
        const event = this.app.workspace.on('layout-change', refresh);
        return () => this.app.workspace.offref(event);
      });
      if (generation !== this.generation) cleanup(); else this.cleanup = cleanup;
    } catch {
      if (generation === this.generation) this.contentEl.setText('The project view could not start.');
      console.error('PROJECT_VIEW_MOUNT_FAILED');
    }
  }
  dispose(): void {
    this.generation++; const cleanup = this.cleanup; this.cleanup = undefined;
    try { cleanup?.(); } catch { console.error('PROJECT_VIEW_DISPOSE_FAILED'); }
  }
  async onClose(): Promise<void> { this.dispose(); this.closed(this); }
}
export default class ProjectPlugin extends Plugin {
  onload(): void {
    const views = new Set<ProjectView>();
    this.registerView(viewType, leaf => { const view = new ProjectView(leaf, closed => views.delete(closed)); views.add(view); return view; });
    this.register(() => { for (const view of views) view.dispose(); views.clear(); });
    const open = async (): Promise<void> => {
      try {
        const leaf = this.app.workspace.getLeavesOfType(viewType)[0] ?? this.app.workspace.getLeaf('tab');
        await leaf.setViewState({ type: viewType, active: true }); await this.app.workspace.revealLeaf(leaf);
      } catch { new Notice('Unable to open the project view.'); console.error('PROJECT_VIEW_OPEN_FAILED'); }
    };
    this.addCommand({ id: 'open-workspace', name: 'Open workspace', callback: () => { void open(); } });
    this.addRibbonIcon('layout-dashboard', 'Open workspace', () => { void open(); });
  }
}

