import { createInterface } from 'node:readline/promises';
import { stdin, stdout, stderr } from 'node:process';
import { createSession, project } from '../../core/project.ts';
async function run(): Promise<void> {
  const args = process.argv.slice(2), json = args.includes('--json');
  const words = args.filter(value => value !== '--json'), session = createSession();
  if (!words.length && stdin.isTTY && stderr.isTTY && !json && (!process.env.CI || process.env.CI === 'false')) {
    const controller = new AbortController(), cancel = () => controller.abort();
    process.once('SIGINT', cancel); process.once('SIGTERM', cancel);
    const terminal = createInterface({ input: stdin, output: stderr });
    try {
      stderr.write(project.pages.map(page => `${page.slug}: ${page.label}`).join('\n') + '\n');
      words.push(await terminal.question('Choose a command ID (or help): ', { signal: controller.signal }));
    } catch (error) { if (controller.signal.aborted) { process.exitCode = 130; return; } throw error; }
    finally { terminal.close(); process.removeListener('SIGINT', cancel); process.removeListener('SIGTERM', cancel); }
  }
  try {
    if (words.length > 2 || (words.length > 1 && words[0] !== 'show')) throw new Error('CLI_ARGUMENT');
    const command = words[0] ?? 'help';
    const data = ['help', '--help', 'list'].includes(command)
      ? { name: project.name, commands: project.pages.map(page => ({ id: page.slug, title: page.label })), usage: 'help | list | show <id> | <id> [--json]' }
      : { surface: session.select(command === 'show' ? words[1] ?? '' : command), status: 'scaffold-not-business-complete' };
    stdout.write(JSON.stringify({ protocolVersion: 1, status: 'ok', data }, null, json ? undefined : 2) + '\n');
  } catch (error) {
    const message = error instanceof Error ? error.message : 'CLI_FAILED'; process.exitCode = 1;
    if (json) stdout.write(JSON.stringify({ protocolVersion: 1, status: 'failed', diagnostics: [{ code: message }] }) + '\n');
    else stderr.write(message + '. Use help to list available commands.\n');
  }
}
void run().catch(() => { stderr.write('CLI_INPUT_FAILED\n'); process.exitCode = 1; });

