import { readFile, writeFile, mkdir, mkdtemp, readdir, lstat, cp, rename, rm } from 'node:fs/promises';
import { resolve, join, extname } from 'node:path';
import { spawnSync } from 'node:child_process';
const root = process.cwd();
const config = JSON.parse(await readFile('shell.project.json', 'utf8'));
const allowed = ['plugin', 'webapp', 'website', 'cli'];
if (config.schemaVersion !== 1 || !Array.isArray(config.targets) || !config.targets.length ||
    new Set(config.targets).size !== config.targets.length || config.targets.some(target => !allowed.includes(target)) ||
    !['nuxt-ui', 'vanilla', 'angular', 'none'].includes(config.frontend)) throw new Error('PROJECT_CONFIG_INVALID');
const requested = process.argv[2], targets = requested ? [requested] : config.targets;
if (process.argv.length > 3 || targets.some(target => !config.targets.includes(target))) throw new Error('PROJECT_TARGET_UNKNOWN');
async function present(path) {
  try { await lstat(path); return true; } catch (error) { if (error.code === 'ENOENT') return false; throw error; }
}
async function regularTree(path) {
  const info = await lstat(path);
  if (info.isSymbolicLink()) throw new Error('BUILD_OUTPUT_LINK');
  if (info.isDirectory()) for (const name of await readdir(path)) await regularTree(join(path, name));
  else if (!info.isFile()) throw new Error('BUILD_OUTPUT_SPECIAL');
}
async function angularAssets(source, destination) {
  await mkdir(destination, { recursive: true });
  for (const name of await readdir(source, { withFileTypes: true })) {
    const from = join(source, name.name), to = join(destination, name.name);
    if (name.isSymbolicLink()) throw new Error('BUILD_SOURCE_LINK');
    if (name.isDirectory()) await angularAssets(from, to);
    else if (extname(name.name) !== '.ts') {
      if (name.name.endsWith('.html')) await writeFile(to, (await readFile(from, 'utf8')).replaceAll('main.ts', 'main.js'));
      else await cp(from, to);
    }
  }
}
async function prepare() {
  if (config.frontend !== 'angular') return resolve('src');
  const compiled = spawnSync(process.execPath, ['node_modules/@angular/compiler-cli/bundles/src/bin/ngc.js', '-p', 'tsconfig.json'], { stdio: 'inherit' });
  if (compiled.error || compiled.status !== 0) throw new Error('ANGULAR_COMPILE_FAILED', { cause: compiled.error });
  await angularAssets(resolve('src'), resolve('.angular/src'));
  return resolve('.angular/src');
}
const destination = resolve('dist'), lock = resolve('.project-build-lock');
await mkdir(lock); // Fail closed on overlapping builds; never remove another process's lock.
let stage, backup;
try {
  stage = await mkdtemp(resolve('.build-stage-'));
  if (await present(destination)) {
    await regularTree(destination);
    if (requested) await cp(destination, stage, { recursive: true });
  }
  const source = await prepare();
  for (const target of targets) {
    // Third-party bundlers may abort on unhandled rejections. The parent owns cleanup.
    const worker = spawnSync(process.execPath, [resolve('scripts/build-worker.mjs'), target, stage, source], { cwd: root, stdio: 'inherit' });
    if (worker.error || worker.status !== 0) throw new Error('PROJECT_BUILD_WORKER_FAILED', { cause: worker.error });
  }
  if (await present(destination)) {
    backup = await mkdtemp(resolve('.build-backup-'));
    await rename(destination, join(backup, 'dist'));
  }
  try { await rename(stage, destination); }
  catch (error) { if (backup) await rename(join(backup, 'dist'), destination); throw error; }
  if (backup) await rm(backup, { recursive: true, force: true });
} finally {
  try { if (stage) await rm(stage, { recursive: true, force: true }); }
  finally { await rm(lock, { recursive: true }); }
}

