/** Per-surface theme ownership; native host classes win over browser preferences. */
export type ObserveOwner = (refresh: () => void) => () => void;
export function bindTheme(root: HTMLElement, observeOwner?: ObserveOwner): () => void {
  const original = { dark: root.classList.contains('dark'), light: root.classList.contains('light') };
  let owner: Document | undefined, observer: MutationObserver | undefined, media: MediaQueryList | undefined;
  let stop: (() => void) | undefined, closed = false;
  const refresh = () => {
    if (closed) return;
    const document = root.ownerDocument;
    if (document !== owner) {
      observer?.disconnect(); media?.removeEventListener('change', refresh); owner = document;
      const window = document.defaultView;
      if (!window) throw new Error('PROJECT_DOCUMENT_UNAVAILABLE');
      observer = new window.MutationObserver(refresh);
      observer.observe(document.body, { attributes: true, attributeFilter: ['class'] });
      media = window.matchMedia('(prefers-color-scheme: dark)'); media.addEventListener('change', refresh);
    }
    const dark = document.body.classList.contains('theme-dark') || (!document.body.classList.contains('theme-light') && Boolean(media?.matches));
    root.classList.toggle('dark', dark); root.classList.toggle('light', !dark);
  };
  const close = () => {
    if (closed) return; closed = true;
    try { observer?.disconnect(); media?.removeEventListener('change', refresh); stop?.(); }
    finally { root.classList.toggle('dark', original.dark); root.classList.toggle('light', original.light); }
  };
  try { refresh(); stop = observeOwner?.(refresh); return close; }
  catch (error) { close(); throw error; }
}

