/** Isolated bundler process: the supervisor owns staging, promotion and lock cleanup. */
import { readFile, cp, lstat } from 'node:fs/promises';
import { resolve, join, dirname, basename } from 'node:path';
import { build } from 'vite';
const root = process.cwd();
const config = JSON.parse(await readFile('shell.project.json', 'utf8'));
const [target, stage, source] = process.argv.slice(2);
if (process.argv.length !== 5 || !['plugin', 'webapp', 'website', 'cli'].includes(target) || !config.targets.includes(target)) throw new Error('PROJECT_WORKER_TARGET');
if (dirname(resolve(stage)) !== root || !basename(stage).startsWith('.build-stage-')) throw new Error('PROJECT_WORKER_STAGE');
if (![resolve('src'), resolve('.angular/src')].includes(resolve(source))) throw new Error('PROJECT_WORKER_SOURCE');
const stageInfo = await lstat(stage);
if (!stageInfo.isDirectory() || stageInfo.isSymbolicLink()) throw new Error('PROJECT_WORKER_STAGE');
async function emit(target, stage, source) {
  const browser = target === 'webapp' || target === 'website';
  const ui = config.frontend === 'nuxt-ui' && target !== 'cli'
    ? (await import('./bundling/vite-shared.mjs')).sharedConfig() : {};
  if (target !== 'cli' && !ui.css) {
    const { cssOwnership } = await import('./bundling/css-ownership.mjs');
    ui.css = { postcss: { plugins: [cssOwnership(config.id)] } };
  }
  const extension = config.frontend === 'angular' ? 'js' : 'ts';
  const targetRoot = join(source, 'targets', target), outDir = join(stage, target);
  const buildOptions = { ...ui.build, outDir, emptyOutDir: true, target: target === 'cli' ? 'node24' : 'es2022', sourcemap: false };
  if (browser) {
    const entries = target === 'website' ? config.websiteEntries : ['index.html'];
    if (!Array.isArray(entries) || !entries.length || entries.some(path => typeof path !== 'string' || !/^(index\.html|pages\/[a-z0-9-]+\/index\.html)$/.test(path))) throw new Error('WEBSITE_ENTRIES_INVALID');
    buildOptions.rolldownOptions = { input: entries.map(path => join(targetRoot, path)) };
  } else if (target === 'plugin') {
    buildOptions.lib = { entry: join(targetRoot, 'main.' + extension), formats: ['cjs'], fileName: () => 'main.js', cssFileName: 'styles' };
    buildOptions.rolldownOptions = { external: ['obsidian'], output: { exports: 'default' } };
    buildOptions.cssCodeSplit = false;
  } else {
    buildOptions.ssr = join(targetRoot, 'main.' + extension);
    buildOptions.rolldownOptions = { output: { format: 'es', entryFileNames: 'main.mjs', banner: '#!/usr/bin/env node' } };
  }
  const linker = config.frontend === 'angular' ? [(await import('./angular-linker.mjs')).angularLinker()] : [];
  await build({ ...ui, plugins: [...linker, ...(ui.plugins ?? [])], define: { ...(ui.define ?? {}), ...(config.frontend === 'angular' ? { ngDevMode: false, ngJitMode: false } : {}) }, configFile: false, root: browser ? targetRoot : root, base: './', publicDir: false, build: buildOptions });
  if (target === 'plugin') {
    await cp('manifest.json', join(outDir, 'manifest.json'));
  }
  const expected = target === 'plugin' ? ['main.js', 'styles.css', 'manifest.json'] : target === 'cli' ? ['main.mjs'] : target === 'website' ? config.websiteEntries : ['index.html'];
  for (const name of expected) {
    const info = await lstat(join(outDir, name));
    if (!info.isFile() || info.isSymbolicLink() || !info.size) throw new Error('PROJECT_ARTIFACT_INCOMPLETE');
  }
}

await emit(target, stage, source);
